    const dangerColor = resolveThemeColorWithFallback(world, "#ef4444", "tile_danger", "corruptionCrimson", "accent");
    const whiteColor = resolveThemeColorWithFallback(world, "#ffffff", "restorationWhite");

    ctx.save();

    for (let r = minY; r <= maxY; r++) {
      const row = data[r];
